const STATES = {
  'memo-editor': {
    url: b => b + '/',
    setup: async page => {
      await page.waitForSelector('h1', { timeout: 15000 });
      await page.waitForTimeout(1500);
      await page.locator('button[aria-label="New memo"]').first().click();
      await page.waitForSelector('[role="dialog"]', { state: 'visible', timeout: 15000 });
      await page.waitForTimeout(600);
    },
  },
  'view-options': {
    url: b => b + '/',
    setup: async page => {
      await page.waitForSelector('h1', { timeout: 15000 });
      await page.waitForTimeout(1500);
      await page.locator('button[aria-label*="View options"]').first().click();
      await page.waitForSelector('[role="menu"],[role="dialog"],[data-radix-popper-content-wrapper]', { state: 'visible', timeout: 15000 });
      await page.waitForTimeout(600);
    },
  },
  'user-menu': {
    url: b => b + '/',
    setup: async page => {
      await page.waitForSelector('h1', { timeout: 15000 });
      await page.waitForTimeout(1500);
      await page.locator('button[aria-label^="Switch space"]').first().click();
      await page.waitForSelector('[role="menu"],[role="dialog"],[data-radix-popper-content-wrapper]', { state: 'visible', timeout: 15000 });
      await page.waitForTimeout(600);
    },
  },
};
